import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FintechChartProps = Record<string, any>;

const DollarIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
    style={{ width: "100%", height: "100%", transition: "none" }}
  >
    <line x1="12" y1="2" x2="12" y2="22"></line>
    <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path>
  </svg>
);

const CoinIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
    style={{ width: "100%", height: "100%", transition: "none" }}
  >
    <circle cx="12" cy="12" r="10"></circle>
    <circle cx="12" cy="12" r="6" strokeDasharray="3 3"></circle>
  </svg>
);

const FLOATING_ICONS = [
  { id: 1, type: "dollar", x: "12%", y: "75%", size: 45, speed: 0.8 },
  { id: 2, type: "coin", x: "82%", y: "55%", size: 60, speed: 1.2 },
  { id: 3, type: "dollar", x: "70%", y: "25%", size: 35, speed: 0.6 },
  { id: 4, type: "coin", x: "18%", y: "30%", size: 50, speed: 1.0 },
  { id: 5, type: "dollar", x: "28%", y: "60%", size: 40, speed: 0.9 },
  { id: 6, type: "coin", x: "78%", y: "85%", size: 55, speed: 1.1 },
];

const FintechChart: React.FC<FintechChartProps> = ({
  backgroundColor = "#F5F5F7",
  transparentBackground = false,
  durationInSeconds = 8,
  targetAmount = 1000000,
  currencySymbol = "$",
  subtitleText = "in Challenges.",
  chartColor = "#1A4DFF",
  counterColor = "#1D1D1F",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Cinematic 3% push-in
  const globalScale = interpolate(frame, [0, totalFrames], [1, 1.03], {
    extrapolateRight: "clamp",
  });

  // Timings
  const animationStartFrame = 20;
  const animationDuration = fps * 4; // 4 seconds for chart and counter
  const animationEndFrame = animationStartFrame + animationDuration;

  // Counter and Chart Shared Progress
  const easeOutQuart = Easing.bezier(0.25, 1, 0.5, 1);
  const progress = interpolate(
    frame,
    [animationStartFrame, animationEndFrame],
    [0, 1],
    {
      easing: easeOutQuart,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Counter logic
  const currentVal = Math.floor(progress * targetAmount);
  const formattedAmount = `${currencySymbol}${currentVal.toLocaleString("en-US")}`;

  // Chart logic
  const chartDrawOffset = interpolate(progress, [0, 1], [100, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Final highlight state (fades in the bold blue glow at the very end)
  const isComplete = progress === 1;
  const highlightScale = interpolate(progress, [0.95, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Subtitle fade in (happens near the end of the count)
  const subtitleOpacity = interpolate(
    progress,
    [0.8, 1],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const subtitleY = interpolate(
    progress,
    [0.8, 1],
    [20, 0],
    { easing: Easing.out(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "'Inter', sans-serif",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background radial subtle light */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: `radial-gradient(circle at 50% 30%, #FFFFFF 0%, ${backgroundColor} 80%)`,
            transition: "none",
          }}
        />
      )}

      {/* Main cinematic wrapper */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          transform: `scale(${globalScale})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {/* Floating Icons */}
        {FLOATING_ICONS.map((icon) => {
          const yOffset = interpolate(frame, [0, totalFrames], [0, -180 * icon.speed]);
          const rotation = interpolate(frame, [0, totalFrames], [0, 90 * icon.speed]);
          const opacity = interpolate(frame, [0, 45], [0, 0.04], {
            extrapolateRight: "clamp",
          });

          return (
            <div
              key={icon.id}
              style={{
                position: "absolute",
                left: icon.x,
                top: icon.y,
                width: icon.size,
                height: icon.size,
                opacity: opacity,
                transform: `translateY(${yOffset}px) rotate(${rotation}deg)`,
                color: counterColor,
                transition: "none",
              }}
            >
              {icon.type === "dollar" ? <DollarIcon /> : <CoinIcon />}
            </div>
          );
        })}

        {/* Chart SVG Canvas */}
        <svg
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            overflow: "visible",
            transition: "none",
          }}
          viewBox="0 0 1080 1920"
          preserveAspectRatio="xMidYMid slice"
        >
          {/* Chart Glow Path */}
          <path
            d="M -50 1600 C 200 1600, 400 1550, 600 1450 S 900 1350, 950 1300 Q 1020 1200, 1150 900"
            fill="none"
            stroke={chartColor}
            strokeWidth="24"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={chartDrawOffset}
            filter="blur(16px)"
            opacity={0.4}
            style={{ transition: "none" }}
          />
          {/* Chart Core Path */}
          <path
            d="M -50 1600 C 200 1600, 400 1550, 600 1450 S 900 1350, 950 1300 Q 1020 1200, 1150 900"
            fill="none"
            stroke={chartColor}
            strokeWidth="5"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={chartDrawOffset}
            style={{ transition: "none" }}
          />
        </svg>

        {/* Text Container */}
        <div
          style={{
            position: "absolute",
            top: "35%",
            left: 0,
            width: "100%",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 10,
            transition: "none",
          }}
        >
          {/* Crossfading Number Wrapper to maintain layout without jitter */}
          <div
            style={{
              position: "relative",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transition: "none",
            }}
          >
            {/* Invisible baseline to size the container properly */}
            <span
              style={{
                fontSize: 130,
                fontWeight: 700,
                fontVariantNumeric: "tabular-nums",
                letterSpacing: "-3px",
                opacity: 0,
                pointerEvents: "none",
                transition: "none",
              }}
            >
              {formattedAmount}
            </span>

            {/* Default State Number (Dark Grey, Normal) */}
            <span
              style={{
                position: "absolute",
                fontSize: 130,
                fontWeight: 500,
                color: counterColor,
                opacity: 1 - highlightScale,
                fontVariantNumeric: "tabular-nums",
                letterSpacing: "-3px",
                whiteSpace: "nowrap",
                transition: "none",
              }}
            >
              {formattedAmount}
            </span>

            {/* Highlight State Number (Deep Blue, Bold, Glowing) */}
            <span
              style={{
                position: "absolute",
                fontSize: 130,
                fontWeight: 700,
                color: chartColor,
                opacity: highlightScale,
                fontVariantNumeric: "tabular-nums",
                letterSpacing: "-3px",
                whiteSpace: "nowrap",
                textShadow: `0px 8px 32px ${chartColor}66`,
                transition: "none",
              }}
            >
              {formattedAmount}
            </span>
          </div>

          {/* Subtitle */}
          <div
            style={{
              opacity: subtitleOpacity,
              transform: `translateY(${subtitleY}px)`,
              fontSize: 42,
              color: "#86868B",
              fontWeight: 500,
              marginTop: 16,
              letterSpacing: "-0.5px",
              transition: "none",
            }}
          >
            {subtitleText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FintechChart;